import java.util.List;

interface Shape {
    double area();
    String name();
    default String describe() { return name() + " " + Math.round(area() * 100) / 100.0; }
}

class Circle implements Shape {
    private final double r;
    Circle(double r) { this.r = r; }
    public double area() { return Math.PI * r * r; }
    public String name() { return "circle"; }
}

class Rect implements Shape {
    private final double w, h;
    Rect(double w, double h) { this.w = w; this.h = h; }
    public double area() { return w * h; }
    public String name() { return "rect"; }
}

class Triangle implements Shape {
    private final double base, height;
    Triangle(double base, double height) { this.base = base; this.height = height; }
    public double area() { return base * height / 2; }
    public String name() { return "triangle"; }
}

public class Shapes {
    // Works for any Shape, including ones written later.
    public static double totalArea(List<Shape> shapes) {
        double total = 0;
        for (Shape s : shapes) total += s.area();
        return Math.round(total * 100) / 100.0;
    }

    public static String largest(List<Shape> shapes) {
        if (shapes.isEmpty()) return "none";
        Shape best = shapes.get(0);
        for (Shape s : shapes) if (s.area() > best.area()) best = s;
        return best.name();
    }
}

