exercises.solution:
import java.util.List;

interface Damageable {
    void takeDamage(int amount);
    int getHealth();
    default boolean isDestroyed() { return getHealth() <= 0; }
}

class Player implements Damageable {
    private int health = 100;
    public void takeDamage(int amount) { health = Math.max(0, health - amount / 2); }   // armour
    public int getHealth() { return health; }
}

class Crate implements Damageable {
    private int health = 30;
    public void takeDamage(int amount) { health = Math.max(0, health - amount); }
    public int getHealth() { return health; }
}

class Wall implements Damageable {
    private int health = 200;
    public void takeDamage(int amount) {
        if (amount < 10) return;   // too weak to scratch it
        health = Math.max(0, health - amount);
    }
    public int getHealth() { return health; }
}

public class Combat {
    public static int hitAll(List<Damageable> things, int amount) {
        int destroyed = 0;
        for (Damageable d : things) {
            d.takeDamage(amount);
            if (d.isDestroyed()) destroyed++;
        }
        return destroyed;
    }
}

