import java.util.*;

interface Notifier {
    void send(String to, String message);
}

// A fake notifier for tests: remembers instead of sending.
class MemoryNotifier implements Notifier {
    private final List<String> sent = new ArrayList<>();
    public void send(String to, String message) { sent.add(to + ": " + message); }
    public List<String> getSent() { return sent; }
}

public class Reminder {
    private final Notifier notifier;   // SMS, email or a fake: Reminder doesn't care

    public Reminder(Notifier notifier) {
        this.notifier = notifier;
    }

    public int remindLate(Map<String, Integer> daysLate) {
        int sent = 0;
        for (var e : daysLate.entrySet()) {
            int d = e.getValue();
            if (d <= 0) continue;
            notifier.send(e.getKey(), "visit " + d + (d == 1 ? " day late" : " days late"));
            sent++;
        }
        return sent;
    }
}
